import re, sys
sys.path.insert(0, '_tools')
import kbfacts
es = kbfacts.ledger_entries('public/_gaps.md')
kbfacts.link_entries(es)
top = lambda e: (e['explicit'] or e['via_sources'] or ['public/?'])[0].split('/', 1)[1]
SEG = re.compile(r'(?:^|\s)- (?=(?:Resolved|Partly resolved|Narrowed|Closed|Tried) 20)')
REF = re.compile(r'\b([a-z0-9-]+/[a-z0-9-]+\.md):(\d+)')
TAG = re.compile(r'\[(?:DOC|CODE|DER)\b')
cache, bad = {}, []
for e in es:
    if False:
        continue
    for seg in SEG.split(e['text'])[1:]:
        if not re.match(r'(?:Resolved|Partly resolved|Narrowed|Closed) 2026-10-2\d', seg):
            continue
        refs = REF.findall(seg)
        def tagged(p, n):
            if p not in cache:
                try:
                    cache[p] = open('kb/public/' + p, encoding='utf-8').read().split('\n')
                except OSError:
                    cache[p] = []
            L = cache[p]
            return 0 < int(n) <= len(L) and TAG.search(L[int(n) - 1])
        if not refs or not all(tagged(p, n) for p, n in refs):
            bad.append(e['line'])
            break
print(len(bad), 'gap entries with a 2026-10-2x closing note that cites no tagged article fact by path:line', bad)
sys.exit(1 if bad else 0)
